namespace CodexVBE
{
    internal sealed partial class LlmVbeTools
    {
        private static object[] EditorDefinitions => new[] {
            Definition("run_procedure_values", "Invoke one standard-module public Sub/Function via in-process Excel.Application.Run and return scalar/SAFEARRAY values, preserving native lower bounds and lengths. Requires saved exact ExpectedHostPath, current module SHA and ExpectedMode=2. Explicit ByVal scalar/Variant parameters only; arrays require Variant, rank 1/2 rectangular JSON, at most 1024 cells per input and 4096 total. ArgumentNames permits reordered named arguments and omitted optionals. No source helper, class/COM objects, ByRef array writes or ParamArray. One invocation only; poll procedure_values_status. A returned value is not proof of macro correctness; failures after invocation may be uncertain. Other hosts remain unsupported; runtime qualification must be inspected.", new[] { "Project", "Module", "Procedure", "ExpectedSha256", "ExpectedHostPath", "ExpectedMode", "Arguments" }, "Project", "Module", "Procedure", "ExpectedSha256", "ExpectedHostPath", "ExpectedMode", "Arguments", "ArgumentNames"),
            Definition("procedure_values_status", "Inspect a scheduled run_procedure_values by exact Project and Query without executing it again. Returns invocation flag, uncertainty and normalized scalar/array result with its native bounds. Not a proof that arbitrary macro side effects succeeded.", new[] { "Project", "Query" }, "Project", "Query"),
            Definition("preview_procedure_rename", "Preview the rename of one standard-module Public/Private Sub/Function and resolved direct/module/project-qualified calls in the current project. Requires declaration coordinates, Query old name, NewName and source SHA. Option Explicit is required; conditional, dynamic, callback, interface and shadowed binding is refused. Returns ExpectedProjectVersion for all project metadata and sources. External consumers and string references are not rewritten.", new[] { "Project", "Module", "Query", "NewName", "ExpectedSha256", "StartLine", "StartColumn", "ProcKind" }, "Project", "Module", "Query", "NewName", "ExpectedSha256", "StartLine", "StartColumn", "ProcKind"),
            Definition("apply_procedure_rename", "Apply the exact preview_procedure_rename plan using its ExpectedProjectVersion and ExpectedMode=2. All modules are inspected before writes, then each is read back. Partial failures may leave edits: read every module before proceeding. Each edit enters existing per-module history; no atomic transaction or global undo is claimed.", new[] { "Project", "Module", "Query", "NewName", "ExpectedSha256", "StartLine", "StartColumn", "ProcKind", "ExpectedProjectVersion", "ExpectedMode" }, "Project", "Module", "Query", "NewName", "ExpectedSha256", "StartLine", "StartColumn", "ProcKind", "ExpectedProjectVersion", "ExpectedMode"),
            Definition("read_project_protection", "Inspect the native Protection tab of the exact active unprotected project in design mode, then Cancel. Requires project_properties ExpectedProjectVersion and exact ControlCaption for native command 2578 from list_commands. Returns lock state, password presence only and OptionsVersion. Requires InvokeAsync; reads no password and does not save.", new[] { "Project", "ExpectedProjectVersion", "ExpectedMode", "ControlCaption" }, "Project", "ExpectedProjectVersion", "ExpectedMode", "ControlCaption"),
            Definition("set_project_protection", "Configure the native project Protection tab. Action lock reads a user-provided absolute UTF8 password file locally (single line, 1-128 characters, <=512 bytes); its contents are never returned. Action clear clears both secrets and viewing lock on an already unprotected project. Requires read_project_protection ExpectedOptionsVersion plus current project_properties version, ExpectedMode=2 and command 2578 ControlCaption. Requires InvokeAsync and edit policy. Native readback checks checkbox/secret lengths only; save and reopen to qualify persistence. No unlocking bypass or automatic save/retry.", new[] { "Project", "ExpectedProjectVersion", "ExpectedOptionsVersion", "ExpectedMode", "ControlCaption", "Action" }, "Project", "ExpectedProjectVersion", "ExpectedOptionsVersion", "ExpectedMode", "ControlCaption", "Action", "Path"),
            Definition("open_native_ide_dialog", "Queue a recognized native IDE surface without validating it: Action macros (ID930), help (984), print (4) or additional_controls (642). Project must be active in ExpectedMode (1/2), with exact enabled ControlCaption from list_commands. print also requires Module and current ExpectedSha256 and that exact active code pane. No print job, macro run or control installation is submitted. Scheduling is not native success; read navigation/debug dialog separately.", new[] { "Project", "ExpectedMode", "ControlCaption", "Action" }, "Project", "ExpectedMode", "ControlCaption", "Action", "Module", "ExpectedSha256"),
            Definition("preview_fit_form_content", "Preview the size or scroll extent of a native UserForm/Frame/Page/MultiPage container based on its direct children. Action fit_container or fit_scroll_extent. ControlPath or ParentPath selects the container, omitted/UserForm is root. Left/Top are nonnegative padding (0-1000 points). Requires current form_tree ExpectedTreeVersion. Reads native decoration, child bounds and numeric properties; unavailable measurements are refused.", new[] { "Project", "Form", "ExpectedTreeVersion", "Action", "Left", "Top" }, "Project", "Form", "ExpectedTreeVersion", "Action", "Left", "Top", "ControlPath", "ParentPath"),
            Definition("apply_fit_form_content", "Apply the inspected native container fitting calculation using the same fields as preview_fit_form_content and current ExpectedTreeVersion. Re-reads dimensions, inside dimensions and child positions. Partial errors are uncertain; never retry automatically. Does not save; container/host variants require native qualification.", new[] { "Project", "Form", "ExpectedTreeVersion", "Action", "Left", "Top" }, "Project", "Form", "ExpectedTreeVersion", "Action", "Left", "Top", "ControlPath", "ParentPath"),
            Definition("project_collection_state", "Inspect the whole VBProjects collection revision, source hashes, saved states and protection before adding or opening a standalone project.", new string[0]),
            Definition("create_standalone_project", "Create one real standalone project using VBProjects.Add(101), with ExpectedProjectVersion from project_collection_state. All preexisting projects must be unprotected and in design mode. Host refusal or unmatched readback is uncertainty; never substitute import or retry automatically.", new[] { "ExpectedProjectVersion" }, "ExpectedProjectVersion"),
            Definition("open_standalone_project", "Open an existing user-provided absolute .swp file once through VBProjects.Open with project_collection_state ExpectedProjectVersion. Verifies preexisting projects. Native refusal must be inspected, never retried automatically.", new[] { "Path", "ExpectedProjectVersion" }, "Path", "ExpectedProjectVersion"),
            Definition("close_standalone_project", "Remove only the exact saved, unprotected standalone .swp project from VBProjects without deleting its file or discarding edits. Requires project_properties ExpectedProjectVersion and exact ExpectedHostPath. Document-host projects are refused.", new[] { "Project", "ExpectedProjectVersion", "ExpectedHostPath" }, "Project", "ExpectedProjectVersion", "ExpectedHostPath"),
            Definition("list_macros", "Read public standard-module Sub/Function declarations with source SHA and parameters. NativeMacroCandidate is a syntactic nonconditional parameterless public Sub outside Option Private Module, not proven chooser visibility. Query and pagination do not execute code.", new[] { "Project" }, "Project", "Query", "Offset", "Limit"),
            Definition("open_project_help", "Open the existing absolute CHM HelpFile and numeric HelpContextID configured on the exact project, guarded by project_properties ExpectedProjectVersion. Uses native HtmlHelp. A handle does not prove topic existence or permitted content; HLP/web help are refused.", new[] { "Project", "ExpectedProjectVersion" }, "Project", "ExpectedProjectVersion"),
            Definition("read_navigation_surface", "Inspect exposed native project tree (Pane project), toolbox pages/controls (toolbox) or visible macro chooser entries (macros). Returns Control tokens and whole-surface WindowVersion. Toolbox MSAA fallback reads pages only: ObservedSelected is an observation, Selected=null and ActionUnavailableReason prohibit mutations that remain unqualified. Collapsed/inaccessible children or toolbox buttons are not certified absent. Requires InvokeAsync, opens nothing, Query/Offset/Limit optional.", new[] { "Pane" }, "Pane", "Query", "Offset", "Limit"),
            Definition("change_navigation_surface", "Select an exact native node, or expand/collapse an expandable project tree node using Control token and ExpectedWindowVersion from read_navigation_surface. Re-reads native state and changes navigation only. Requires InvokeAsync; no shortcuts or mouse coordinates. Delivery errors are uncertain, never retry automatically.", new[] { "Pane", "Control", "Action", "ExpectedWindowVersion" }, "Pane", "Control", "Action", "ExpectedWindowVersion"),
            Definition("verify_vba_signature_file", "Verify the strongest present VBA signature of a saved Office file using the registered Microsoft x64 Office SIP and Windows Authenticode policy. Path is absolute. Checks the VBA digest/signature and Windows trust policy, cached revocation only, no network, private keys, macro execution or file mutation. Reports VerifierUnavailable when the dedicated SIP is absent; never substitutes certificate_trust or a document signature. Supports the Microsoft SIP Office binary/OOXML formats, not SWP/Access. Unsaved VBE edits are not verified; nonzero Windows results are not reported as trusted.", new[] { "Path" }, "Path"),
            Definition("preview_parameter_rename", "Preview a bound rename of one parameter of a Private Sub/Function in a standard module. Use project_symbols for the exact declaration coordinates and list_procedures for ProcKind=0. Updates local uses and named arguments of direct/module-qualified calls in the same module; preserves unrelated members, strings, comments, labels and nested calls. Rejects public/class/form callbacks, shadowed names, conditional compilation and ambiguous signatures. No project-wide rename is claimed.", new[] { "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "StartLine", "StartColumn", "Query", "NewName" }, "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "StartLine", "StartColumn", "Query", "NewName"),
            Definition("apply_parameter_rename", "Apply the checked private standard-module parameter rename, including named callers in this module, with ExpectedMode=2 and the current SHA. Produces a chat code diff and participates in VBAi undo/redo. Read and compile afterwards. Public parameters, class/form callbacks, conditional binding and project-wide changes are refused.", new[] { "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "ExpectedMode", "StartLine", "StartColumn", "Query", "NewName" }, "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "ExpectedMode", "StartLine", "StartColumn", "Query", "NewName"),
            Definition("preview_local_rename", "Preview a declaration-bound rename of one explicit local variable or constant. Use project_symbols to supply its exact Query name, StartLine/StartColumn, Procedure, ProcKind and module SHA. Keeps qualified members, types, labels, named arguments, strings and comments unchanged. Refuses parameters, conditional code, DefType and collision/ambiguous binding. No project-wide rename is claimed.", new[] { "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "StartLine", "StartColumn", "Query", "NewName" }, "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "StartLine", "StartColumn", "Query", "NewName"),
            Definition("apply_local_rename", "Apply the same checked local declaration rename in design mode. Requires the declaration coordinates from project_symbols, current module SHA and ExpectedMode=2. Emits a chat code diff and joins VBAi undo/redo; read and compile the module afterwards. Project-wide symbols and parameters remain refused.", new[] { "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "ExpectedMode", "StartLine", "StartColumn", "Query", "NewName" }, "Project", "Module", "Procedure", "ProcKind", "ExpectedSha256", "ExpectedMode", "StartLine", "StartColumn", "Query", "NewName"),
            Definition("toolbar_controls", "Inspect one exact normal VBE toolbar: ordered command IDs, captions, tags and controls revision. list_toolbars supplies the collection revision. Menus and context menus are excluded.", new[] { "ObjectName" }, "ObjectName"),
            Definition("create_toolbar", "Create an empty custom normal toolbar named VBAi - <ObjectName>, Temporary defaults to true for this host session; false saves a host-scoped private SQLite profile, restored when VBAi loads. Requires ExpectedToolbarCollectionVersion from list_toolbars; never overwrites an existing bar. Use add_toolbar_command to populate it. Native errors and profile restoration errors must be inspected; persistence was qualified in Excel.", new[] { "ObjectName", "ExpectedToolbarCollectionVersion" }, "ObjectName", "ExpectedToolbarCollectionVersion", "Temporary"),
            Definition("remove_toolbar", "Remove only an empty custom VBAi - toolbar with current collection and controls revisions. Built-in/third-party bars and nonempty bars are refused.", new[] { "ObjectName", "ExpectedToolbarCollectionVersion", "ExpectedToolbarControlsVersion" }, "ObjectName", "ExpectedToolbarCollectionVersion", "ExpectedToolbarControlsVersion"),
            Definition("add_toolbar_command", "Add a native built-in button (Temporary defaults to true; false saves a SQLite profile on a custom VBAi toolbar created with Temporary=false) to a normal customizable toolbar. Requires its current controls revision and exact built-in ControlId/ControlCaption from list_commands. InsertIndex is one-based, default append. No arbitrary OnAction or macro code; the new button receives a VBAi ownership tag. Native errors/partial results require inspection, never automatic retry.", new[] { "ObjectName", "ExpectedToolbarControlsVersion", "ControlId", "ControlCaption" }, "ObjectName", "ExpectedToolbarControlsVersion", "ControlId", "ControlCaption", "InsertIndex", "Temporary"),
            Definition("remove_toolbar_command", "Remove only a VBAi-added button at the exact one-based InsertIndex after verifying controls revision, ControlId and ControlCaption. Existing built-in/third-party controls are protected.", new[] { "ObjectName", "ExpectedToolbarControlsVersion", "ControlId", "ControlCaption", "InsertIndex" }, "ObjectName", "ExpectedToolbarControlsVersion", "ControlId", "ControlCaption", "InsertIndex"),
            Definition("set_code_view", "Switch the entire code window containing the inspected pane to Action procedure or module. Both split panes share this setting. Requires its current Pane token, WindowVersion, source SHA and expected design/break mode; StartLine must identify a valid source line. Uses the native owner-drawn view toolbar with coordinates relative to its verified HWND geometry (no global pointer movement). Re-reads CodePaneView and source SHA in all one or two panes. Unknown geometry, stale panes and modal windows are refused. Persistence and alternate DPI profiles are not qualified.", new[] { "Project", "Module", "Pane", "ExpectedWindowVersion", "ExpectedSha256", "ExpectedMode", "StartLine", "Action" }, "Project", "Module", "Pane", "ExpectedWindowVersion", "ExpectedSha256", "ExpectedMode", "StartLine", "Action"),
            Definition("run_form", "Queue native Run (186) for an exact UserForm designer in design mode. Requires current code SHA from read_module, TreeVersion from form_tree and exact enabled ControlCaption from list_commands. Rechecks both revisions and component identity before execution. Runs Initialize/Activate and arbitrary user event code; normal execution approval applies. Queuing/command return does not prove display or initialization. Read form_run_status and debug_dialog; no automatic retry.", new[] { "Project", "Form", "ExpectedMode", "ExpectedSha256", "ExpectedTreeVersion", "ControlCaption" }, "Project", "Form", "ExpectedMode", "ExpectedSha256", "ExpectedTreeVersion", "ControlCaption"),
            Definition("form_run_status", "Read a queued native UserForm run by its exact Project and OperationId in Query. Keeps the last 20 commands in this session. Running or CommandReturned may coexist with a modal form or diagnostic; RuntimeVerified remains false without independent runtime evidence.", new[] { "Project", "Query" }, "Project", "Query"),
            Definition("list_object_browser", "Read native Object Browser items from Pane classes, members or libraries. Query is an optional case-insensitive label substring filter; Offset is zero-based, Limit defaults to 50 (maximum 200). Does not open or change the browser. Reports an unidentifiable or empty native list as unavailable, never assumes it is empty. Pages describe live UI state and can change between calls.", new[] { "Pane" }, "Pane", "Query", "Offset", "Limit"),
            Definition("select_object_browser", "Select an exact library (Context), class (ObjectName) and/or member (Procedure). Context alone changes only the library; Procedure requires ObjectName in the already open native Object Browser. Uses English/French accessible labels and refuses duplicate names. Only navigates; no code execution or editing. A missing member may leave the class selected: read_object_browser reports current state. Selection readback does not certify semantic resolution; inspect the native description.", new string[0], "ObjectName", "Procedure", "Context"),
            Definition("read_object_browser", "Read the visible native Object Browser selections and description using accessibility on a worker thread. Supports English/French window titles. Does not open or change the browser. Reports unavailable or unreadable controls explicitly. Selected labels and description are native observations, not a semantic resolution guarantee.", new string[0]),
            Definition("set_window_state", "Restore, minimize or maximize an exact VBE window using Action restore/minimize/maximize and its current window_layout revision. Linked panes must target their containing frame instead. Re-reads the native state; the caption can change. May affect other document windows in the native MDI workspace. Does not verify persistence across restart.",
                new[] { "WindowCaption", "WindowType", "ExpectedWindowVersion", "Action" }, "WindowCaption", "WindowType", "ExpectedWindowVersion", "Action"),
            Definition("code_pane_layout", "Inspect already-open code panes for the exact project/module without opening or activating one. Returns per-pane token, WindowVersion, source Sha256, selection and TopLine, including split panes. Tokens expire on the next code_pane_layout call in this session. Destroyed native split-pane entries are reported in UnavailablePanes and receive no token.",
                new[] { "Project", "Module" }, "Project", "Module"),
            Definition("scroll_code_pane", "Scroll a specific inspected code pane so StartLine is at its top without changing its selection or source. Requires its current Pane token and ExpectedWindowVersion, source SHA and expected design/break mode. Native clamping or selection changes remain unverified. Does not open panes or verify persistence.",
                new[] { "Project", "Module", "Pane", "ExpectedWindowVersion", "ExpectedSha256", "ExpectedMode", "StartLine" }, "Project", "Module", "Pane", "ExpectedWindowVersion", "ExpectedSha256", "ExpectedMode", "StartLine"),
            Definition("native_code_navigation", "Queue native Definition (Action definition, ID 939) or Last Position (Action last_position, ID 1822). Supply exact enabled ControlCaption, Project, Module, source SHA, expected mode, StartLine/StartColumn/EndColumn and, for definition, the exact selected Expression. Last Position requires that selection already active. Query status with Action status and Query=OperationId. Scheduling is not success: inspect status and destination via code_panes/read_module. Native dialogs may remain open even after command completion; inspect debug_dialog when no navigation is observed. Source changes before execution refuse the command. Does not edit code or certify semantic resolution.",
                new[] { "Action" }, "Action", "Query", "Project", "Module", "ExpectedSha256", "ExpectedMode", "StartLine", "StartColumn", "EndColumn", "Expression", "ControlCaption"),
            Definition("editor_layout", "Read the geometry and revision of all visible, unlinked VBE document windows (code, designers, object browser). Scope spans all open projects. Returns WindowVersion for arrange_editor_windows.", new string[0]),
            Definition("arrange_editor_windows", "Arrange all visible document windows across projects using Action cascade, tile_vertical or tile_horizontal. Requires current editor_layout WindowVersion and exact native ControlCaption from list_commands (IDs 1826, 2561, 2562 respectively). Requires 2-64 windows; verifies identities and resulting geometry. Irregular or unsupported layouts remain VerificationPending, not successful. Does not alter source or verify persistence across restart.",
                new[] { "Action", "ExpectedWindowVersion", "ControlCaption" }, "Action", "ExpectedWindowVersion", "ControlCaption"),
            Definition("set_code_split", "Set the selected module to two code panes (Action split) or one pane (Action unsplit). Requires current code SHA, StartLine, expected break/design mode and exact ControlCaption for native command ID 302 from list_commands. Activates that module and verifies its CodePanes count. Repeating the requested state does not toggle again. Does not edit code or verify persistence after restarting the host.",
                new[] { "Project", "Module", "ExpectedSha256", "StartLine", "ExpectedMode", "Action", "ControlCaption" }, "Project", "Module", "ExpectedSha256", "StartLine", "ExpectedMode", "Action", "ControlCaption"),
            Definition("set_form_list_binding", "Generate or replace the protected list block in UserForm_Initialize with an Excel RowSource binding to ThisWorkbook, using literal SheetName and bounded A1 RangeAddress (up to 10000 rows, 10 columns). Requires a saved Excel project matching ExpectedHostPath, current tree/code revisions and an existing ColumnCount matching the range width. Supports nested controls. Does not edit worksheet cells or designer properties. The source sheet must exist; worksheet availability, runtime values and persistence require a separate host check. ItemsWritten=0 because rows are read from the sheet at runtime.",
                new[] { "Project", "Form", "ControlPath", "ExpectedHostPath", "ExpectedTreeVersion", "ExpectedSha256", "SheetName", "RangeAddress" }, "Project", "Form", "ControlPath", "ExpectedHostPath", "ExpectedTreeVersion", "ExpectedSha256", "SheetName", "RangeAddress"),
            Definition("set_addin_connection", "Connect or disconnect an already registered VBE add-in using its exact ProgId and AddInVersion from list_addins. Action connect/disconnect. Refuses VBAi itself, stale or ambiguous identities, and verifies Connect by a fresh lookup. May execute third-party initialization or cleanup code. Native failure is not retried or claimed rolled back. Does not install add-ins, alter host COMAddIns or configure loading at startup.",
                new[] { "ProgId", "ExpectedAddInVersion", "Action" }, "ProgId", "ExpectedAddInVersion", "Action"),
            Definition("window_layout", "Read exact VBE window bounds and frame membership, with WindowVersion for subsequent layout mutations. An unreadable property yields no usable version.",
                new[] { "WindowCaption", "WindowType" }, "WindowCaption", "WindowType"),
            Definition("set_window_bounds", "Set integer native bounds of a standalone normal-state VBE window or frame. Requires current window_layout revision, verifies exact readback and attempts rollback on failure. Does not verify persistence across host restart.",
                new[] { "WindowCaption", "WindowType", "ExpectedWindowVersion", "Left", "Top", "Width", "Height" }, "WindowCaption", "WindowType", "ExpectedWindowVersion", "Left", "Top", "Width", "Height"),
            Definition("link_vbe_window", "Link a VBE tool pane to an existing linked frame or unlink it to a floating frame. Action link also requires TargetWindowCaption, TargetWindowType and ExpectedTargetWindowVersion from window_layout. Checks source and destination revisions and re-reads membership. Native failures may partially alter topology and return VerificationPending; never assume an automatic rollback or persistence across restart.",
                new[] { "WindowCaption", "WindowType", "ExpectedWindowVersion", "Action" }, "WindowCaption", "WindowType", "ExpectedWindowVersion", "Action", "TargetWindowCaption", "TargetWindowType", "ExpectedTargetWindowVersion"),
            Definition("project_symbols", "Search live project modules, Sub/Function/Property definitions, variables, constants, parameters, types, fields and enum members. Query filters by name; WholeWord requires exact names, MatchCase controls casing. Offset/Limit paginate (maximum 200). Returns source SHA and definition lines, and per-module errors. Declaration symbols include physical line/column, scope, type and conditional-branch flags. This is a syntax index; implicit variables and semantic/COM binding are not inferred.",
                new[] { "Project" }, "Project", "Module", "Query", "WholeWord", "MatchCase", "Offset", "Limit"),
            Definition("navigate_code", "Navigate to a verified source position (Action go; Module, ExpectedSha256, StartLine and StartColumn required), or move through VBAi navigation history (Action back/forward). A new go clears forward history. Each stack holds at most 100 positions in this session; stale positions are refused and retained. Project name and saved file path resolve to the same macro. Does not edit source.",
                new[] { "Project", "Action" }, "Project", "Action", "Module", "ExpectedSha256", "StartLine", "StartColumn"),
            Definition("code_bookmark", "Manage macro-scoped code bookmarks with Action add/list/remove/go. Query is the bookmark name. Add requires Module, ExpectedSha256, StartLine and StartColumn. Navigation refuses a changed source revision. Saved macros persist up to 200 bookmarks per absolute file path in local SQLite; unsaved projects remain session-only. Save As or moving a macro creates a different scope. Does not edit source.",
                new[] { "Project", "Action" }, "Project", "Action", "Query", "Module", "ExpectedSha256", "StartLine", "StartColumn"),
            Definition("preview_form_layout", "Preview group layout in one UserForm container. Items contains 2-64 canonical control paths; the first anchors alignment and sizing. Action: align_left/right/top/bottom, align_centers (same horizontal center as first control), align_middles (same vertical center), same_width/height/size, distribute_horizontal/vertical, center_horizontal/vertical or snap_grid (Width is grid spacing in points). Also space_horizontal/vertical (Width is exact gap, zero removes gaps), increase_horizontal_spacing/increase_vertical_spacing and decrease_horizontal_spacing/decrease_vertical_spacing (Width is gap delta). Spacing keeps the leftmost/topmost control fixed, sorts by position and refuses overlaps or container overflow. Does not mutate controls.",
                new[] { "Project", "Form", "ExpectedTreeVersion", "Items", "Action" }, "Project", "Form", "ExpectedTreeVersion", "Items", "Action", "Width"),
            Definition("apply_form_layout", "Apply the group geometry plan with tree-version checking, bounds checking, COM readback and rollback on failure. Does not save the macro. See preview_form_layout for actions and Items.",
                new[] { "Project", "Form", "ExpectedTreeVersion", "Items", "Action" }, "Project", "Form", "ExpectedTreeVersion", "Items", "Action", "Width"),
            Definition("set_form_tab_order", "Set the tab order of every direct control in a UserForm or canonical ParentPath container. Items must enumerate all direct control names exactly once, in the requested order. Verifies every TabIndex and attempts rollback on failure.",
                new[] { "Project", "Form", "ExpectedTreeVersion", "Items" }, "Project", "Form", "ExpectedTreeVersion", "Items", "ParentPath"),
            Definition("preview_code_edit", "Preview an explicit module line-range transformation without modifying VBA. Action: replace (literal Query/Text, optional WholeWord and MatchCase), replace_identifier (Query/NewName, excludes strings/comments; lexical only, not semantic symbol resolution), comment, uncomment, indent or unindent (InsertIndex is the indentation width, 1-16). Inspect the proposed source before applying it.",
                new[] { "Project", "Module", "ExpectedSha256", "StartLine", "Count", "Action" }, "Project", "Module", "ExpectedSha256", "StartLine", "Count", "Action", "Query", "Text", "NewName", "WholeWord", "MatchCase", "InsertIndex"),
            Definition("apply_code_edit", "Apply the same bounded line-range transformations as preview_code_edit, under current SHA and design-mode checks. Changes produce an inline diff and enter VBAi's session undo history. replace_identifier is lexical and must not be represented as a semantic project-wide rename.",
                new[] { "Project", "Module", "ExpectedSha256", "StartLine", "Count", "Action" }, "Project", "Module", "ExpectedSha256", "StartLine", "Count", "Action", "Query", "Text", "NewName", "WholeWord", "MatchCase", "InsertIndex"),
            Definition("list_toolbars", "Read normal VBE toolbars: exact Name, visibility, enabled/protection state, geometry, visibility WindowVersion and full ToolbarLayoutVersion. Menu bars and popup menus are excluded. Does not change the layout.", new string[0]),
            Definition("set_toolbar_placement", "Place a normal toolbar without changing its docking mode. Action float requires explicit integral ToolbarLeft and ToolbarTop screen pixels on an already floating bar; Action row requires positive RowIndex on an already docked bar. Exact ObjectName and fresh ExpectedToolbarLayoutVersion required. Native normalization or partial failure yields Verified=false and observed After; do not blindly retry. May rearrange neighboring toolbars; persistence not verified.",
                new[] { "ObjectName", "ExpectedToolbarLayoutVersion", "Action" }, "ObjectName", "ExpectedToolbarLayoutVersion", "Action", "ToolbarLeft", "ToolbarTop", "RowIndex"),
            Definition("set_toolbar_position", "Dock a normal VBE toolbar left/top/right/bottom or float it (Action). Requires exact ObjectName and ExpectedToolbarLayoutVersion from list_toolbars. Refuses stale geometry, disabled bars and protected movement/docking. Re-reads position and checks visibility was preserved. Can rearrange neighboring toolbars; does not set exact coordinates/row or claim persistence across restart.",
                new[] { "ObjectName", "ExpectedToolbarLayoutVersion", "Action" }, "ObjectName", "ExpectedToolbarLayoutVersion", "Action"),
            Definition("set_toolbar_visibility", "Show or hide one normal VBE toolbar by exact ObjectName from list_toolbars, requiring its ExpectedWindowVersion. Refuses menu bars, popup menus, hiding protected bars and showing disabled bars. Re-reads visibility; does not enable a bar or change protection. Affects host-wide VBE UI, not macro code. Persistence across restart is not verified.",
                new[] { "ObjectName", "ExpectedWindowVersion", "Action" }, "ObjectName", "ExpectedWindowVersion", "Action"),
            Definition("read_runtime_forms", "Read visible native UserForm runtime frame windows in this host process, including caption, HWND, enabled state, owner and bounds. Works while a modal form is open. Does not read controls or values and does not map a window to a macro: ProjectIdentityVerified is false. Hidden forms and other window classes are excluded. Use alongside form_run_status/debug_state; a modeless form can remain visible in mode 2.", new string[0]),
            Definition("read_code_clipboard", "Read Unicode text from the Windows clipboard (up to 1 Mi characters) and its Version. This is system-wide clipboard content, not scoped to the macro. Use only when clipboard content is relevant to the user's request. Does not modify code or clipboard.", new string[0]),
            Definition("copy_code", "Copy an explicit nonempty code range to the Windows Unicode clipboard, replacing its contents. Requires current module SHA. One-based character columns; EndLine/EndColumn is exclusive. Does not change code or native selection.",
                new[] { "Project", "Module", "ExpectedSha256", "StartLine", "StartColumn", "EndLine", "EndColumn" }, "Project", "Module", "ExpectedSha256", "StartLine", "StartColumn", "EndLine", "EndColumn"),
            Definition("cut_code", "Copy an explicit code range to Windows clipboard, verify that copy, then remove the range under source SHA and design-mode guards. Produces a chat diff and VBAi undo entry. Clipboard contains the copied text even if the subsequent code edit fails. Uses the same exclusive range as copy_code.",
                new[] { "Project", "Module", "ExpectedSha256", "StartLine", "StartColumn", "EndLine", "EndColumn" }, "Project", "Module", "ExpectedSha256", "StartLine", "StartColumn", "EndLine", "EndColumn"),
            Definition("paste_code", "Replace the explicit exclusive code range with Windows clipboard Unicode text. An empty range inserts; an empty module uses 1:1 to 1:1. Requires current module SHA, design mode and ExpectedClipboardVersion from read_code_clipboard. Refuses changed clipboard and unsupported control characters. Normalizes pasted line endings to CRLF and produces a chat diff plus VBAi undo entry. Read back if VBE normalized the text.",
                new[] { "Project", "Module", "ExpectedSha256", "ExpectedClipboardVersion", "StartLine", "StartColumn", "EndLine", "EndColumn" }, "Project", "Module", "ExpectedSha256", "ExpectedClipboardVersion", "StartLine", "StartColumn", "EndLine", "EndColumn"),
            Definition("form_clipboard_state", "Read exact UserForm container selection, full tree, SelectionVersion, Windows ClipboardVersion and CanPaste in design mode. Optional canonical ParentPath targets a Frame or Page; omitted targets root. No binary clipboard data is sent to the model.",
                new[] { "Project", "Form" }, "Project", "Form", "ParentPath"),
            Definition("select_form_controls", "Replace one Designer container's selection with Items (exact direct control names, 0-64; empty clears). Optional canonical ParentPath targets Frame/Page, omitted root. Requires ExpectedDesignerSelectionVersion from form_clipboard_state of the same container. Resolves all names before writes; re-reads selection. Other container selections remain independent; no focus or clipboard change.",
                new[] { "Project", "Form", "Items", "ExpectedDesignerSelectionVersion" }, "Project", "Form", "Items", "ExpectedDesignerSelectionVersion", "ParentPath"),
            Definition("recover_form_cut", "Recover a session cut in the same live Project/Form/ParentPath using DesignerClipboardRecoveryId and fresh selection/clipboard revisions. Refuses observed intervening Designer changes or duplicate controls; unreadable properties cannot be compared. Replaces clipboard, pastes once, restores original names/bounds/container tab order, then reports remaining property differences and read errors. Not a full fidelity guarantee or native undo. Paste attempt consumes automatic recovery; do not retry a partial failure. Does not save.",
                new[] { "Project", "Form", "DesignerClipboardRecoveryId", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion" }, "Project", "Form", "DesignerClipboardRecoveryId", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion", "ParentPath"),
            Definition("restore_form_clipboard", "Republish an in-memory DesignerClipboardRecoveryId returned by a cut, after the system clipboard was replaced. Requires the same live Project/Form/ParentPath and current selection/clipboard revisions. Latest 8 cuts, max 8 MiB each, session only. Reports omitted formats. Does not paste or undo: inspect the tree before explicit native_form_clipboard paste; native paste can change geometry.",
                new[] { "Project", "Form", "DesignerClipboardRecoveryId", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion" }, "Project", "Form", "DesignerClipboardRecoveryId", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion", "ParentPath"),
            Definition("native_form_clipboard", "Copy, cut or paste (Action) using the exact native UserForm container's current selection. Optional canonical ParentPath targets Frame/Page, omitted root. Requires ExpectedDesignerSelectionVersion=SelectionVersion and ExpectedClipboardVersion from form_clipboard_state of that container. Refuses stale selection/tree/clipboard. Copy and cut replace the system clipboard; paste uses this container's selection context. Reports observed tree differences, not binary fidelity; event code is not transferred. No retry on partial failure. COM edits may not enter native undo history. Cut first retains readable MSForms clipboard formats in session memory and returns DesignerClipboardRecoveryId; capture failure prevents removal.",
                new[] { "Project", "Form", "Action", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion" }, "Project", "Form", "Action", "ExpectedDesignerSelectionVersion", "ExpectedClipboardVersion", "ParentPath"),
            Definition("native_form_history", "Undo or redo one native action on the exact UserForm Designer using UndoAction/RedoAction. Action is undo or redo. Requires design mode and ExpectedTreeVersion from form_tree, including its current CanUndo/CanRedo state. Re-reads the entire nested tree and reports DesignerChanges; availability flags alone do not count as an edit. COM property assignments may not enter this native history. Does not save; do not retry automatically if pending.",
                new[] { "Project", "Form", "Action", "ExpectedTreeVersion" }, "Project", "Form", "Action", "ExpectedTreeVersion"),
            Definition("native_code_history_state", "Inspect shared native Undo/Redo commands and code revisions for all modules in the only open project. Returns HistoryVersion. Refuses multiple projects, UserForms and non-design mode. The native stack can affect another module than the active one; individual stack entries are unavailable.",
